using StackExchange.Redis;

var connection = ConnectionMultiplexer.Connect("redis-demo.redis.cache.windows.net:6380,password=<key>,ssl=True,abortConnect=False");
var db = connection.GetDatabase();

// Set a value with 1-hour expiration
await db.StringSetAsync("user:101:name", "Ada Lovelace", TimeSpan.FromHours(1));

// Get the value
string? name = await db.StringGetAsync("user:101:name");
Console.WriteLine(name);
